from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self._books = set()                # all known book ids
        self._loans = {}                   # book_id -> (user, borrow_day)
        self._fines = {}                   # user -> unpaid fine total
        self._user_books = {}              # user -> set of borrowed book ids

    def add_book(self, book_id: str) -> None:
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self._loans:
            raise ValueError(f"Book already borrowed: {book_id}")
        held = self._user_books.get(user, set())
        if len(held) >= 1:
            raise ValueError(f"User {user} already holds a book")
        self._loans[book_id] = (user, day)
        self._user_books.setdefault(user, set()).add(book_id)

    @staticmethod
    def _count_weekdays(start: date, end: date) -> int:
        """Number of weekdays strictly after `start` up to and including `end`."""
        if end <= start:
            return 0
        days = 0
        d = start + timedelta(days=1)
        while d <= end:
            if d.weekday() < 5:  # Mon-Fri
                days += 1
            d += timedelta(days=1)
        return days

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self._loans:
            raise ValueError(f"Book not borrowed: {book_id}")
        borrower, borrow_day = self._loans[book_id]
        if borrower != user:
            raise ValueError(f"Book {book_id} was not borrowed by {user}")

        due = borrow_day + timedelta(days=self.loan_days)
        # If due date falls on a weekday boundary, define delay as weekdays in (due, day].
        # Days of delay = number of weekdays strictly after due date, up to and including return day.
        late_days = self._count_weekdays(due, day)
        fine = late_days * self.daily_fine

        del self._loans[book_id]
        self._user_books[user].discard(book_id)
        if not self._user_books[user]:
            del self._user_books[user]

        if fine > 0:
            self._fines[user] = self._fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines.pop(user, None)
